CREATE TABLE IF NOT EXISTS groups (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, workspace_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(190) NOT NULL, description VARCHAR(500) NULL, deleted_at TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_groups_workspace_slug (workspace_id, slug), KEY idx_groups_workspace (workspace_id), CONSTRAINT fk_groups_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS group_members (group_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (group_id, user_id), KEY idx_group_members_user (user_id), CONSTRAINT fk_group_members_group FOREIGN KEY (group_id) REFERENCES groups (id) ON DELETE CASCADE, CONSTRAINT fk_group_members_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collection_user_permissions (collection_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role ENUM("admin","editor","viewer") NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (collection_id, user_id), KEY idx_cup_user (user_id), CONSTRAINT fk_cup_collection FOREIGN KEY (collection_id) REFERENCES collections (id) ON DELETE CASCADE, CONSTRAINT fk_cup_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collection_group_permissions (collection_id BIGINT UNSIGNED NOT NULL, group_id BIGINT UNSIGNED NOT NULL, role ENUM("admin","editor","viewer") NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (collection_id, group_id), KEY idx_cgp_group (group_id), CONSTRAINT fk_cgp_collection FOREIGN KEY (collection_id) REFERENCES collections (id) ON DELETE CASCADE, CONSTRAINT fk_cgp_group FOREIGN KEY (group_id) REFERENCES groups (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS document_user_permissions (document_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role ENUM("admin","editor","viewer") NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (document_id, user_id), KEY idx_dup_user (user_id), CONSTRAINT fk_dup_document FOREIGN KEY (document_id) REFERENCES documents (id) ON DELETE CASCADE, CONSTRAINT fk_dup_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS document_group_permissions (document_id BIGINT UNSIGNED NOT NULL, group_id BIGINT UNSIGNED NOT NULL, role ENUM("admin","editor","viewer") NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (document_id, group_id), KEY idx_dgp_group (group_id), CONSTRAINT fk_dgp_document FOREIGN KEY (document_id) REFERENCES documents (id) ON DELETE CASCADE, CONSTRAINT fk_dgp_group FOREIGN KEY (group_id) REFERENCES groups (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
